  "topic": "Advent Co case",
  "marks": 2,
  "scenario": "Advent Co is a publicly listed company. Details of Advent Co's non-current assets at 1 October 20X8 were:\n\n | Land and building ($m) | Plant ($m) | Telecommunications licence ($m) | Total ($m)\nCost/valuation | 280 | 150 | 300 | 730\nAccumulated depreciation/amortisation | (40) | (105) | (30) | (175)\nCarrying amount | 240 | 45 | 270 | 555\n\nThe following information is relevant:\n\n(1) The land and building were revalued on 1 October 20X3 with $80 million attributable to the land and $200 million to the building. At that date the estimated remaining life of the building was 25 years. A further revaluation was not needed until 1 October 20X8 when the land and building were valued at $85 million and $180 million respectively. The remaining estimated life of the building at this date was 20 years.\n\n(2) Plant is depreciated at 20% per annum on cost with time apportionment where appropriate. On 1 April 20X9, new plant costing $45 million was acquired. In addition, this plant cost $5 million to install and commission. No plant is more than four years old.\n\n(3) The telecommunications licence was bought from the government on 1 October 20X7 and has a ten-year life. It is amortised on a straight-line basis. In September 20X9, a review of the sales of the products related to the licence showed them to be very disappointing. As a result of this review the estimated recoverable amount of the licence at 30 September 20X9 was estimated at only $100 million.\n\nThere were no disposals of non-current assets during the year to 30 September 20X9.",
  "question": "Advent Co's licence is now carried at its recoverable amount. Complete the statement using the options provided.\n\nThe recoverable amount of an asset is the higher of ___ (blank 1) and ___ (blank 2).",
  "type": "match",
