  "explanation": "Provisions can arise from both constructive and legal obligations. Discounting is permitted (and required, if material) when estimating a provision. The costs of retraining or relocating continuing staff are specifically excluded from a restructuring provision under IAS 37 - only direct expenditures caused by the restructuring, not associated with the ongoing activities of the entity, may be included. A restructuring provision may only be recognised once there is a detailed formal plan and a valid expectation has been raised in those affected by starting to implement it or announcing it publicly."
