  "scenario": "Derringdo Co is a broadband provider which receives government assistance to provide broadband to remote areas. Derringdo Co invested in a new server at a cost of $800,000 on 1 October 20X2. The server has an estimated useful life of ten years with a residual value equal to 15% of its cost. Derringdo Co uses straight-line depreciation on a time apportioned basis.\n\nThe company received a government grant of 30% of its cost price of the server at the time of purchase. The terms of the grant are that if the company retains the asset for four years or more, then no repayment liability will be incurred. Derringdo Co has no intention of disposing of the server within the first four years. Derringdo Co's accounting policy for capital-based government grants is to treat them as deferred income and release them to income over the life of the asset to which they relate.",
  "question": "Derringdo Co is carrying out a transaction on behalf of another entity and the finance director is unsure whether Derringdo Co should be regarded as an agent or a principal in respect of this transaction.\n\nWhich of the following would indicate that Derringdo Co is acting as an agent?",
  "type": "single",
