  "question": "Rather than take out a loan specifically for the new store Apex Co could have funded the store from existing borrowings which are: (1) 10% bank loan $50 million (2) 8% bank loan $30 million. In this case it would have applied a 'capitalisation rate' to the expenditure on the asset. What would that rate have been?",
