  "scenario": "The carrying amount of Julian Co's property, plant and equipment at 31 December 20X3 was $310,000 and the tax written down value was $230,000.\n\nThe following data relates to the year ended 31 December 20X4:\n\n(1) At the end of the year the carrying amount of property, plant and equipment was $460,000 and the tax written down value was $270,000. During the year some items were revalued upwards by $90,000. No items had previously required revaluation. In the tax jurisdiction in which Julian Co operates revaluations of assets do not affect the tax base of an asset or taxable profit. Gains due to revaluations are taxable on sale.\n\n(2) Julian Co began development of a new product during the year and capitalised $60,000 in accordance with IAS 38 Intangible Assets. The expenditure was deducted for tax purposes as it was incurred. None of the expenditure had been amortised by the year end.\n\nThe corporate income tax rate is 30%. The current tax charge was calculated for the year as $45,000.",
