  "question": "During January 20X2, before the financial statements of Rainbird Co for the year ended 31 December 20X1 had been finalised, a number of events took place. Identify whether each of these events would require an adjustment to the financial statements as at 31 December 20X1 in accordance with IAS 10 Events After the Reporting Period.",
