  "scenario": null,
  "question": "IAS 21 The Effects of Changes in Foreign Exchange Rates sets out how entities that carry out transactions in a foreign currency should measure the results of these transactions at the year end. Using the pull-down list options provided, select which exchange rate should non-monetary items carried at historical cost be measured?",
